\textbf{২. বেগ (Velocity)}: আমরা জানি সময় সাপেক্ষে সরণের পরিবর্তনের হারকে বেগ বলে। একে সাধারণত $v$ দ্বারা প্রকাশ করা হয়।

\begin{equation}
\therefore \text{বেগ, } v = \frac{d}{dt} (x) = \frac{d}{dt} (A \sin \omega t) = A \omega \cos \omega t \quad \text{এখানে, } x = A \sin \omega t
\end{equation}

\begin{equation}
\therefore \sin \omega t = \frac{x}{A} \text{ এবং } \cos \omega t = \sqrt{1 - \sin^2 \omega t}
\end{equation}

\begin{equation}
\therefore \text{বেগ, } v = A \omega \sqrt{1 - \sin^2 \omega t} = A \omega \sqrt{1 - x^2 / A^2}
\end{equation}

