\subsection{Differential equation of simple harmonic motion}
মনে করি $m$ ভরবিশিষ্ট একটি বস্তুকাণ সরল দোলন গতিতে আছে। $t$ সময়ে এর সরণ $x$ হলে
বেগ, $v=\frac{dx}{dt}$ এবং ত্বরণ, $a=\frac{d^2x}{dt^2}$

\begin{equation}
\therefore \quad \text{কণটির ওপর ক্রিয়াশীল বলের মান,}
\end{equation}

\begin{equation}
F'=\text{ভর} \times \text{ত্বরণ} = ma = m\frac{d^2x}{dt^2}
\end{equation}

যেহেতু বল বা ত্বরণ সরণের সমানুপাতিক এবং বিপরীতমূখী, অতএব

\begin{equation}
m\frac{d^2x}{dt^2} \propto -x
\end{equation}

\begin{equation}
\text{বা,} \quad m\frac{d^2x}{dt^2} = -Kx
\end{equation}

\begin{equation}
\text{বা,} \quad \frac{d^2x}{dt^2} = \frac{-K}{m}x
\end{equation}

