\[
m = 40 \text{ g} = 0.04 \text{ kg}
\]
\[
A = 12 \text{ cm} = 0.12 \text{ m}
\]
\[
x = 6 \text{ cm} = 0.06 \text{ m}
\]
\[
T = 1.5 \text{ s}
\]
\[
v = ?
\]
\[
K = ?
\]

এখানে,
\[
A = 0.01 \text{ m}
\]
\[
f = 12 \text{ Hz}
\]
\[
x = \frac{A}{2} = \frac{0.01}{2} = 0.005 \text{ m}
\]
\[
\omega = 2\pi f = 2\pi \times 12 = 75.398 \text{ rad s}^{-1}
\]
\[
v = \omega \sqrt{A^2 - x^2} = 75.398 \sqrt{(0.01)^2 - (0.005)^2} = 75.398 \times 0.009979 = 0.75 \text{ m s}^{-1}
\]

