\subsection{উল্লম্ব স্পিং-এর দোলন (Oscillation of a vertical spring)}

স্পিং-এর এক প্রান্ত দুই অবলম্বনে অটোকিয়ে অপর প্রান্তে একটি তর খুলিয়ে সামন্য টেনে ছেড়ে দিলে তা ওপর-নিচে সরল দোলন গতিতে সন্ধিত হতে থাকে। 8.10 (ক) চিত্রে তর খুলিয়ে সামন্য টেনে ছেড়ে দিলে তা ওপর-নিচে সরল দোলন গতিতে সন্ধিত হতে থাকে। এ অবস্থায় স্পিংটির অবস্থা দেখলো হয়েছে। এ অবস্থায় স্পিংটির মুক্ত প্রান্ত P অবস্থানে ছিল। স্পিংটির মুক্ত প্রান্তে m ভরের একটি বস্তু খুলিয়ে সামন্য টেনে ছেড়ে দিলে তা ওপর-নিচে সরল দোলন গতিতে সন্ধিত হতে থাকে। এ অবস্থায় স্পিংটির প্রত্যানক বল F বস্তুর ওজনের সমান হয় এবং বস্তুর ওজন স্পিং-এর প্রত্যানক বল F_{0} দ্বারা প্রশমিত হয়।

\begin{equation}
\text{সূত্রাং } F_{0} = -mg
\end{equation}

\begin{equation}
\text{স্পিংটি স্বিভিশাপক সীমার মধ্যে টানা হলে }
\end{equation}

\begin{equation}
F_{0} = -Kl
\end{equation}

\begin{equation}
\therefore \quad mg = Kl
\end{equation}

এখন m ভরটিকে টেনে ছেড়ে দিলে তরটি Q-কে সামন্যবস্থানে রেখে A বিস্তারে সন্ধিত হতে থাকবে। ধরা যাক t সময়ে স্পিং অবস্থান হতে x সরণ প্রাপ্ত হবে। এই অবস্থায় স্পিংটির প্রত্যানক বল, F_{1} = -K(x + l) [চিত্র 8.10(গ)]।

\begin{equation}
\text{সূত্রাং, ভরটির ওপর নিট বল, } F = F_{1} + mg
\end{equation}

\begin{equation}
= -Kx - Kl + mg
\end{equation}

\begin{equation}
= -Kx - Kl + Kl
\end{equation}

\begin{equation}
= -Kx
\end{equation}

এই বলের ক্রিয়ায় m ভরের বস্তুটি a ত্বরণ প্রাপ্ত হলে

\begin{equation}
ma = -Kx
\end{equation}

\begin{equation}
\text{বা, } a = \frac{-K}{m}x \quad [\because K, m \text{ ধ্রুবক}]
\end{equation}

\begin{equation}
\therefore \quad a \propto x
\end{equation}

অর্ধাং ত্বরণ সরণের সমানুপাতিক ও বিপরীতমুখী। এটি সরল ছন্দিত গতির একটি শর্ত। সূত্রাং স্পিং-এর গতি সরল ছন্দিত গতি।

\begin{equation}
\text{বুলন্ট ভর m এর গতির জন্য নিম্নলিখিত শর্ত সাপেক্ষে সরল দোলকের গতি সরল দোলন গতি হবে—}
\end{equation}

\begin{equation}
\text{এ শর্ত কি? উত্তর দিন।}
\end{equation}

