\section{পর্যাবৃত্ত গতি}

মাটির নিচে বা উচু পাহাড়ের ওপর $g$-এর মান কম। কাজেই উচু পাহাড়ে বা মাটির নিচে দোলকের দোলন কাল বেশি হয়। এর অর্ধ ঘড়ি ধীরে চলে। বিশ্বে অঞ্চলে $g$-এর মান কম এবং মেরু অঞ্চলে $g$-এর মান বেশি। অতএব একটি দোলক ঘড়িকে বিশ্বে অঞ্চল হতে মেরু অঞ্চলে নিলে ঘড়িটি দৃত চলে।

\subsection{দোলনকালের হিসাব:}

আমরা জানি, $1$ দিন $= 86400$ সেকেন্ড

সূতরাং সঠিক সময় নির্দেশকারী একটি দোলক ঘড়ি দিনে $86400$টি অর্ধ দোলন দেয়। দোলক ঘড়ি ধীরে বা দৃত চললে দোলনকালের হিসাব নিম্নরূপ হবে—

(i) ধীরে চলার ক্ষেত্রে : মনে করি একটি দোলক ঘড়ি দিনে $n$ সেকেন্ড ধীরে চলে।

\begin{align*}
\therefore \text{দোলকটি } (86400 - n) \text{ টি অর্ধ দোলন দেয়} &= 86400 \text{ সেকেন্ড} \\
\therefore \text{1 টি} \quad \text{”} \quad \text{”} &= \frac{86400}{86400 - n} \text{ সেকেন্ড} \\
\therefore \text{2 টি} \quad \text{”} \quad \text{”} &= \frac{2 \times 86400}{86400 - n} \text{ সেকেন্ড}
\end{align*}

\begin{align*}
\therefore \text{দিনে } n \text{ সেকেন্ড ধীরে চললে দোলনকাল হবে} &= \frac{2 \times 86400}{86400 - n} \text{ সেকেন্ড} \\
\end{align*}

(ii) দৃত চলার ক্ষেত্রে : দোলক ঘড়ি দিনে $n$ সেকেন্ড দৃত চললে,

\begin{align*}
\therefore \text{দোলকটি } (86400 + n) \text{ টি অর্ধ দোলন দেয়} &= 86400 \text{ সেকেন্ড} \\
\therefore \text{1 টি} \quad \text{”} \quad \text{”} &= \frac{86400}{86400 + n} \text{ সেকেন্ড} \\
\therefore \text{2 টি} \quad \text{”} \quad \text{”} &= \frac{2 \times 86400}{86400 + n} \text{ সেকেন্ড}
\end{align*}

\begin{align*}
\therefore \text{দিনে } n \text{ সেকেন্ড দৃত চললে দোলনকাল হবে} &= \frac{2 \times 86400}{86400 + n} \text{ সেকেন্ড} \\
\end{align*}

